<?php
matinf_theme_heading('Isplanirajte svoj akademski dan.','Nastava i ispitni rokovi za izabrani program i godinu, pregledno na jednom mjestu.','RASPORED');
$programs=get_posts(['post_type'=>'mf_program','post_status'=>'publish','has_password'=>false,'numberposts'=>-1,'orderby'=>'title','order'=>'ASC']);
if(!$programs) { echo '<p class="empty">Raspored još nije dostupan.</p>'; return; }
$groups=matinf_program_groups();
$default_program=$groups['undergraduate']['items'][0]??$programs[0];
$pid=matinf_theme_int('program_id',$default_program->ID);
if(!in_array($pid,array_column($programs,'ID'),true)) $pid=$default_program->ID;
$duration=min(4,max(1,(int)get_post_meta($pid,'_matinf_durationYears',true)));
$year=min($duration,max(1,matinf_theme_int('study_year',1))); $semester=matinf_theme_int('semester',1)===2?2:1;
$view=isset($_GET['view']) && is_string($_GET['view']) ? sanitize_key($_GET['view']) : 'classes'; if(!in_array($view,['classes','exams','graduate'],true)) $view='classes';
$day=min(5,matinf_theme_int('weekday',0));
$result=matinf_schedule_result(['program_id'=>$pid,'year'=>$year,'semester'=>$semester]);
$selection=['program_id'=>$pid,'study_year'=>$year,'semester'=>$semester,'view'=>$view]; $url=get_permalink($args['post']);
?>
<form class="catalog-filters schedule-choice" method="get" action="<?php echo esc_url($url); ?>"><input type="hidden" name="view" value="<?php echo esc_attr($view); ?>"><label>Studijski program<select name="program_id"><?php foreach($groups as $group) { echo '<optgroup label="'.esc_attr($group['label']).'">'; foreach($group['items'] as $program) if(matinf_is_public($program->ID,'mf_program')) echo '<option data-duration="'.min(4,max(1,(int)get_post_meta($program->ID,'_matinf_durationYears',true))).'" value="'.$program->ID.'" '.selected($pid,$program->ID,false).'>'.esc_html($program->post_title).'</option>'; echo '</optgroup>'; } ?></select></label><label>Godina<select name="study_year"><?php for($i=1;$i<=$duration;$i++) echo '<option value="'.$i.'" '.selected($year,$i,false).'>'.$i.'. godina</option>'; ?></select></label><label>Semestar<select name="semester"><option value="1" <?php selected($semester,1); ?>>Zimski</option><option value="2" <?php selected($semester,2); ?>>Ljetni</option></select></label><button class="button">Prikaži raspored</button></form>
<div class="schedule-context"><div><span class="eyebrow">TRENUTNI IZBOR</span><h2><?php echo esc_html(get_the_title($pid)); ?></h2><p><?php echo $view==='graduate'?'Predmeti 4. godine':$year.'. godina · '.($semester===1?'Zimski':'Ljetni').' semestar'; ?></p></div><?php if(!is_wp_error($result)) echo '<span class="academic-year">'.esc_html($result['academicYear']).'</span>'; ?></div>
<nav class="pill-nav schedule-tabs" aria-label="Vrsta rasporeda"><?php foreach(['classes'=>'Nastava','exams'=>'Ispiti','graduate'=>'Apsolventski rokovi'] as $key=>$label) echo '<a '.($key===$view?'aria-current="page"':'').' href="'.esc_url(add_query_arg(array_merge($selection,['view'=>$key]),$url)).'">'.esc_html($label).'</a>'; ?></nav>
<?php if(is_wp_error($result)) { echo '<p class="empty">'.esc_html($result->get_error_message()).'</p>'; return; }
if($view==='classes') : $days=[0=>'Cijela sedmica',1=>'Ponedjeljak',2=>'Utorak',3=>'Srijeda',4=>'Četvrtak',5=>'Petak']; ?>
<nav class="weekday-nav" aria-label="Dan nastave"><?php foreach($days as $key=>$label) echo '<a '.($key===$day?'aria-current="page"':'').' href="'.esc_url(add_query_arg(array_merge($selection,['weekday'=>$key]),$url)).'">'.esc_html($label).'</a>'; ?></nav>
<div class="timetable"><?php foreach($days as $key=>$label) : if(!$key || ($day && $day!==$key)) continue; $rows=array_filter($result['items'],fn($row)=>(int)$row['day']===$key); ?><section class="timetable-day"><header><span class="eyebrow">NASTAVA</span><h2><?php echo esc_html($label); ?></h2></header><div><?php foreach($rows as $row) : ?><article class="lesson"><div class="lesson-time"><strong><?php echo esc_html($row['start']); ?></strong><span><?php echo esc_html($row['end']); ?></span></div><div><span class="tag"><?php echo esc_html($row['kind']); ?></span><h3><a href="<?php echo esc_url($row['course']['url']); ?>"><?php echo esc_html($row['course']['title']); ?></a></h3><p><?php if(!empty($row['staff'])) echo '<a href="'.esc_url($row['staff']['url']).'">'.esc_html($row['staff']['title']).'</a>'; ?></p></div><span class="room-label"><?php echo esc_html($row['room']); ?></span></article><?php endforeach; if(!$rows) echo '<p class="day-empty">Nema planirane nastave.</p>'; ?></div></section><?php endforeach; ?></div>
<?php else : $rows=$view==='graduate'?$result['graduateExams']:$result['exams']; ?>
<section class="exam-panel"><div class="section-heading"><div><p class="eyebrow">ISPITNI KALENDAR</p><h2><?php echo $view==='graduate'?'Apsolventski rokovi':'Raspored ispita'; ?></h2></div><p><?php echo $view==='graduate'?'Odabrani predmeti četvrte godine.':'Termini za izabrani program i godinu.'; ?></p></div>
<?php $periods=[]; foreach($rows as $row) $periods[$row['period']][]=$row;
foreach($periods as $period=>$entries) : ?><details class="exam-period" open><summary><?php echo esc_html($period); ?><span><?php echo count($entries); ?> termina</span></summary><div class="table-scroll" role="region" aria-label="<?php echo esc_attr($period); ?>" tabindex="0"><table class="schedule-table"><thead><tr><th>Predmet</th><th>Datum</th><th>Vrijeme</th><th>Učionica</th><th>Nastavnik</th></tr></thead><tbody><?php foreach($entries as $row) : ?><tr><td><a href="<?php echo esc_url($row['course']['url']); ?>"><?php echo esc_html($row['course']['title']); ?></a></td><td><?php echo esc_html(implode('.',array_reverse(explode('-',$row['date']))).'.'); ?></td><td><?php echo esc_html($row['start'].(!empty($row['end'])?'–'.$row['end']:'')); ?></td><td><?php echo esc_html($row['room']); ?></td><td><?php echo esc_html($row['staff']['title']??'—'); ?></td></tr><?php endforeach; ?></tbody></table></div></details><?php endforeach; if(!$rows) echo '<p class="empty">Nema objavljenih termina za ovaj izbor.</p>'; ?></section>
<?php endif; ?>
